      'peakShaving',
      'gridConstraints',
      'storage',
      'storageFarm',
      'thermal',
      'heatingRod',
      'bhkw',
      'generator',
      'threshold',
      'relay',
      'aiAdvisor',
      'energyWallet',
      'tariffProvider',
      'energyLedger',
      'chargeKiosk',
      'meshMicrogrid',
      'netOperatorInterface',
      'operatingStrategies',
      'smartHome',
      'smartHomeConfig',

