          mode: 'hybrid',
          voltageLevel: 'MS',
          thresholdPercent: 20,
          minShiftW: 100000,
          annualPeakReferenceW: 0,
          targetLimitW: 0,
          safetyMarginW: 0,
          includeWeekends: false,
          excludeChristmasNewYear: true,
          highLoadWindows: [],
