      const norm = this.nwNormalizeEmsApps(mergedForApps);
      const prev = out.emsApps;
      out.emsApps = norm;
      try {
        const a = JSON.stringify(prev || {});
        const b = JSON.stringify(norm || {});
        if (a != b) changed = true;
      } catch (_e) {
        changed = true;
      }
