        gridTargetW: calculation.ok ? calculation.gridTargetW : null,
        minPowerW: Number.isFinite(minPowerW) ? Math.round(minPowerW) : null,
        maxPowerW: Number.isFinite(maxPowerW) ? Math.round(maxPowerW) : null,
