              const modeRaw = String(dev.mode || 'pvAuto').trim().toLowerCase();
              const cfgMode = (modeRaw === 'manual' || modeRaw === 'off') ? modeRaw : 'pvAuto';

              let userEnabled = true;
              let userMode = 'inherit';
